const BY_KEY = new Map<string, AtlasSheet>();
for (const s of ATLAS) BY_KEY.set(`${s.node}:${s.kind}`, s);

export function sheetFor(node: number, kind: 'c' | 'r' | 'n'): AtlasSheet | undefined {
  return BY_KEY.get(`${node}:${kind}`);
}
